// SEM IA: números da semana do Zezinho (últimos 7 dias).
const desde = $now.minus({ days: 7 });
const av = $('Avaliações da semana').all().map(i => i.json).filter(r => r.id);
const NOMES = { relatorio_diario: 'Relatório diário', avaliacao_reuniao: 'Feedback de reunião', resposta: 'Respostas a menções', avaliacao_relatorio: 'Avaliação de relatório' };
const linhas = [];
for (const [tipo, nome] of Object.entries(NOMES)) {
  const r = av.filter(x => x.tipo === tipo);
  if (!r.length) continue;
  const c = s => r.filter(x => x.status === s).length;
  const notas = r.map(x => Number(x.nota)).filter(n => n > 0 && tipo !== 'avaliacao_relatorio');
  const media = notas.length ? (notas.reduce((a, b) => a + b, 0) / notas.length).toFixed(1).replace('.', ',') : '—';
  const decididos = c('aprovado') + c('publicado_auto') + c('rejeitado');
  const taxa = decididos ? Math.round((c('aprovado') + c('publicado_auto')) / decididos * 100) + '%' : '—';
  linhas.push('• *' + nome + '*: ' + r.length + ' | ✅ ' + c('aprovado') + ' | 🤖 auto ' + c('publicado_auto') + ' | ❌ ' + c('rejeitado') + ' | ⏳ ' + c('pendente') + ' | expirou ' + c('expirado') + ' | aprovação ' + taxa + (tipo !== 'avaliacao_relatorio' ? ' | juiz ' + media : ''));
}
const cons = $('Consumo de IA').all().map(i => i.json).filter(r => r.dia);
const semana = cons.filter(r => r.dia >= desde.toFormat('yyyy-MM-dd'));
const soma = l => l.reduce((s, r) => s + Number(r.custo_brl || 0), 0);
const brl = v => 'R$ ' + v.toFixed(2).replace('.', ',');
const porOrigem = {};
semana.forEach(r => { porOrigem[r.origem] = (porOrigem[r.origem] || 0) + Number(r.custo_brl || 0); });
const regrasNovas = $('Regras novas').all().map(i => i.json).filter(r => r.descricao).map(r => '• ' + String(r.descricao).slice(0, 160));
const ex = ((($('n8n - erros da semana').first() || {}).json || {}).data || []).filter(e => new Date(e.startedAt) >= new Date(desde.toISO()));
const errosPorFluxo = {};
ex.forEach(e => { errosPorFluxo[e.workflowId] = (errosPorFluxo[e.workflowId] || 0) + 1; });
const conteudo = [
  '*Aprovações (7 dias)*',
  linhas.length ? linhas.join('\n') : '• Nada enviado para aprovação.',
  '',
  '*Custo da semana (registrado):* ' + brl(soma(semana)) + Object.entries(porOrigem).map(([o, v]) => ' | ' + o + ' ' + brl(v)).join('') + '\n_Relatório = estimado; confira o real no AI Studio. Total desde a compra: ' + brl(soma(cons)) + ' de R$ 70._',
  '',
  '*Regras novas aprendidas:* ' + regrasNovas.length + (regrasNovas.length ? '\n' + regrasNovas.slice(0, 6).join('\n') : ''),
  '',
  '*Erros nos fluxos:* ' + (ex.length ? ex.length + ' (' + Object.entries(errosPorFluxo).map(([w, n]) => w + ': ' + n).join(', ') + ')' : 'nenhum'),
  '',
  '_Meta da nota 9: ≥ 90% aprovado sem correção por 2-3 semanas. Peça ao Claude: "revisão semanal do Zezinho"._'
].join('\n');
return [{ json: { titulo: '📈 Zezinho — semana até ' + $now.setZone('America/Sao_Paulo').toFormat('dd/MM'), conteudo } }];
